(()=>{const result={},e=document.createElement('div'),s=e.style;for(const name of ['font-size','width','--custom']){s.cssText='';s.setProperty(name,'12px');s.setProperty(name,'150px !important');result[name]=[s.getPropertyValue(name),s.getPropertyPriority(name)];s.setProperty(name,'150px','important');result[name+'Valid']=[s.getPropertyValue(name),s.getPropertyPriority(name)]}s.cssText='font-size: 150px ! important; width: 20px !/**/IMPORTANT; --text: "!important";';result.text=[s.fontSize,s.getPropertyPriority('font-size'),s.width,s.getPropertyPriority('width'),s.getPropertyValue('--text')];s.fontSize='12px';s.fontSize='150px !important';result.assignment=s.fontSize;return result})()